// Administravimo lentele: miniatiura + paaiskinimas
add_filter('manage_rk_galerija_posts_columns', function ($cols) {
    $new = array('cb' => $cols['cb'], 'rk_thumb' => 'Nuotrauka', 'title' => 'Aprasymas (rodomas po nuotrauka)');
    foreach ($cols as $k => $v) { if (!isset($new[$k]) && $k !== 'cb' && $k !== 'title') $new[$k] = $v; }
    return $new;
});
add_action('manage_rk_galerija_posts_custom_column', function ($col, $id) {
    if ($col === 'rk_thumb') echo get_the_post_thumbnail($id, array(90, 68), array('style' => 'border-radius:8px;object-fit:cover'));
}, 10, 2);
