// Kategorija -> paslaugos puslapis (term meta, redaguojama kategorijos formoje)
add_action('rk_gal_kat_add_form_fields', function () {
    echo '<div class="form-field"><label>Rodyti puslapyje</label>' . rk_gal_page_select('') . '<p>Paslaugos puslapis, kuriame bus rodoma si galerija.</p></div>';
});
add_action('rk_gal_kat_edit_form_fields', function ($term) {
    echo '<tr class="form-field"><th><label>Rodyti puslapyje</label></th><td>' . rk_gal_page_select(get_term_meta($term->term_id, 'rk_page', true)) . '</td></tr>';
});
function rk_gal_page_select($cur) {
    $out = '<select name="rk_page"><option value="">- nerodyti -</option>';
    foreach (get_pages(array('sort_column' => 'menu_order,post_title')) as $p) {
        $out .= '<option value="' . (int) $p->ID . '"' . selected((int) $cur, (int) $p->ID, false) . '>' . esc_html($p->post_title) . '</option>';
    }
    return $out . '</select>';
}
$rk_gal_save_term = function ($term_id) { if (isset($_POST['rk_page'])) update_term_meta($term_id, 'rk_page', (int) $_POST['rk_page']); };
add_action('created_rk_gal_kat', $rk_gal_save_term);
add_action('edited_rk_gal_kat', $rk_gal_save_term);

// Galerijos HTML pagal puslapio ID
function rk_gal_render_for_page($page_id) {
    $terms = get_terms(array('taxonomy' => 'rk_gal_kat', 'hide_empty' => false, 'meta_key' => 'rk_page', 'meta_value' => (int) $page_id));
    if (is_wp_error($terms) || !$terms) return '';
    $term = $terms[0];
    $q = new WP_Query(array('post_type' => 'rk_galerija', 'posts_per_page' => -1, 'orderby' => array('menu_order' => 'ASC', 'date' => 'DESC'), 'tax_query' => array(array('taxonomy' => 'rk_gal_kat', 'terms' => $term->term_id)), 'no_found_rows' => true));
    if (!$q->posts) return '';
    $items = '';
    foreach ($q->posts as $p) {
        $tid = get_post_thumbnail_id($p->ID); if (!$tid) continue;
        $full = wp_get_attachment_image_url($tid, 'full'); $mid = wp_get_attachment_image_url($tid, 'large');
        $cap = esc_html(get_the_title($p));
        $items .= '<a class="rkg-it" href="' . esc_url($full) . '" target="_blank" rel="noopener"><img loading="lazy" src="' . esc_url($mid) . '" alt="' . $cap . '"><span class="rkg-cap">' . $cap . '</span></a>';
    }
    if (!$items) return '';
    return '<section class="blk rkg"><div class="wrap"><div class="sec-head"><h2>M&#363;s&#371; darbai</h2><span class="more">' . esc_html($term->name) . ' &middot; ' . count($q->posts) . ' nuotr.</span></div><div class="rkg-grid">' . $items . '</div></div></section>';
}
add_filter('elementor/widget/render_content', function ($content, $widget) {
    if (strpos($content, 'class="blk rkg"') === false) return $content;
    $html = rk_gal_render_for_page(get_the_ID());
    return preg_replace('/<section class="blk rkg">.*?<\/section>/s', $html, $content, 1);
}, 9, 2);

// Vienkartine migracija: esamos 187 nuotraukos -> Galerijos irasai
add_action('init', function () {
    if (get_option('rk_galmod_migrated')) return;
    if (!current_user_can('manage_options')) return;
    $r = wp_remote_get('https://raw.githubusercontent.com/rimvydaskvikas/rk-img/master/gal_captions.json', array('timeout' => 30));
    $map = json_decode(wp_remote_retrieve_body($r), true);
    if (!$map) return;
    $cats = array('atrakinimas' => array('Avarinis atrakinimas', 38), 'gamyba' => array('Rakt&#371; gamyba ir remontas', 39), 'programavimas' => array('Rakt&#371; programavimas', 40), 'spynos' => array('Spyn&#371; remontas', 41));
    $tids = array();
    foreach ($cats as $slug => $c) {
        $t = term_exists($slug, 'rk_gal_kat');
        if (!$t) $t = wp_insert_term(html_entity_decode($c[0], ENT_QUOTES, 'UTF-8'), 'rk_gal_kat', array('slug' => $slug));
        $tid = is_array($t) ? (int) $t['term_id'] : (int) $t;
        update_term_meta($tid, 'rk_page', $c[1]); $tids[$slug] = $tid;
    }
    $media = get_posts(array('post_type' => 'attachment', 'posts_per_page' => -1, 'post_status' => 'any', 'fields' => 'ids', 's' => 'Darbu pavyzdys'));
    $n = 0;
    foreach ($media as $mid) {
        $file = basename(get_attached_file($mid)); $key = preg_replace('/-\d+(\.jpg)$/', '$1', $file);
        if (!isset($map[$key])) continue;
        $pid = wp_insert_post(array('post_type' => 'rk_galerija', 'post_status' => 'publish', 'post_title' => $map[$key][1], 'menu_order' => ++$n));
        if ($pid) { set_post_thumbnail($pid, $mid); wp_set_object_terms($pid, $tids[$map[$key][0]], 'rk_gal_kat'); }
    }
    update_option('rk_galmod_migrated', $n, false);
}, 30);
